// 原prepare/apply的无费控制组件；不把外层wait推进伪装成本域收费或完成。
#define main private_shop_original_travel_expense_main
#include "private_shop_travel_expense_source_test.cpp"
#undef main
#include "resident/domains/commerce/freight/private_shop_travel_control_source.hpp"
namespace {
// 同一真正已开始的道路/地形行旅按原规则暂停、复行、等待。
void no_fee_controls(bool terrain_mode){Fixture f;if(terrain_mode){terrain::TerrainMap map;map.id="map";map.width=40;map.height=20;map.cell_size=20;map.cells.resize(2);map.budgets={{terrain::Mode::foot,10},{terrain::Mode::army,10},{terrain::Mode::boat,10}};map.money_per_tick=7;map.fatigue_per_tick=2;require(terrain::validate_map(map).ok,"original control terrain");f.catalog.world_map_id=map.id;f.catalog.maps.insert(map.id,map);f.catalog.settlements.find("A")->map_xy={10,10};f.catalog.settlements.find("B")->map_xy={30,10};}auto id=f.begin("carrier","B");
 for(const TravelCommandPayload command:{TravelCommandPayload{PauseTravelCommand{}},TravelCommandPayload{ResumeTravelCommand{}},TravelCommandPayload{TravelWaitCommand{}}}){
 auto prepared=prepare_travel_control(f.common,f.travel,f.catalog,f.services,"carrier",command);require(prepared.ok,"actual original control quote");require(f.common.begin_resource_execution_capture().ok,"start actual control capture");auto b=capture_private_shop_travel_control_boundary(f.common,f.travel,prepared.value);require(b.ok,"original no-fee boundary");std::optional<TravelControlDraft> draft;require(apply_travel_control(f.common,f.travel,f.catalog,prepared.value,&draft).ok&&draft.has_value(),"actual control writer");auto read=read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,*draft);require(read.ok,"read exact actual no-fee source");check(f.funds("carrier")==100&&f.common.tick()==0&&f.common.resource_execution_drafts().empty(),"no prepayment or clock inferred from wait");
 auto bad=*draft;bad.original_control.command=ReturnTravelCommand{};check(!read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,bad).ok,"return cannot replace no-fee command");bad=*draft;bad.original_control.actor_id="other";check(!read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,bad).ok,"other actual actor rejected");bad=*draft;bad.original_control.quote=TravelQuote{};check(!read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,bad).ok,"a quote cannot be added to no-fee command");bad=*draft;bad.before.action.remaining_ticks++;check(!read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,bad).ok,"original action before cannot change");
 f.common.state().identity.tick++;check(!read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,*draft).ok,"outer later advance cannot reuse control boundary");f.common.state().identity.tick--;require(f.common.apply_resources({{WalletDelta{"wallet.carrier",0,true}},{}}).ok,"actual extra zero resource recipe");check(!read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,*draft).ok,"zero recipe is not free original control");require(f.common.finish_resource_execution_capture().ok,"end real capture");require(f.common.begin_resource_execution_capture().ok,"restart same capture address");check(!read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,*draft).ok,"old control boundary rejected on restart");require(f.common.finish_resource_execution_capture().ok,"finish restarted capture");
 }
 auto replan=prepare_travel_control(f.common,f.travel,f.catalog,f.services,"carrier",ReturnTravelCommand{});if(terrain_mode){check(!replan.ok&&replan.error.original.code=="AlreadyThere","original terrain zero-distance return remains rejected");replan=prepare_travel_control(f.common,f.travel,f.catalog,f.services,"carrier",RerouteCommand{StableId{"B"},{}});}require(replan.ok,"actual separate replan prepared");require(f.common.begin_resource_execution_capture().ok,"capture return exclusion");check(!capture_private_shop_travel_control_boundary(f.common,f.travel,replan.value).ok,"real replan requires different source contract");
}
// 原兼容缺paused键时只能在原末尾追加该键；不是只比较一个布尔值。
void legacy_paused_field(){Fixture f;auto id=f.begin("carrier","B");auto* road=f.travel.road_actions.find(id);road->has_paused=false;road->field_order={"path","edge_index","returning","reverse_first","payer_wallet_id"};auto prepared=prepare_travel_control(f.common,f.travel,f.catalog,f.services,"carrier",PauseTravelCommand{});require(prepared.ok,"legacy original pause prepare");require(f.common.begin_resource_execution_capture().ok,"legacy actual capture");auto b=capture_private_shop_travel_control_boundary(f.common,f.travel,prepared.value);require(b.ok,"legacy boundary");std::optional<TravelControlDraft> draft;require(apply_travel_control(f.common,f.travel,f.catalog,prepared.value,&draft).ok&&draft.has_value(),"legacy writer appends key");require(read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,*draft).ok,"exact original appended paused accepted");check(f.travel.road_actions.find(id)->field_order.back()=="paused","old field insertion sequence retained");auto changed=*draft;std::get<RoadTravelParams>(*changed.before.params).met_actions.push_back("unserialized-contact");check(!read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,changed).ok,"unserialized original optional value still exact");f.travel.road_actions.find(id)->field_order.pop_back();check(!read_private_shop_travel_no_fee_control(f.common,f.travel,b.value,*draft).ok,"removed real appended field rejected");}
}
int main(){try{no_fee_controls(false);no_fee_controls(true);legacy_paused_field();}catch(const std::exception& e){check(false,e.what());}std::cout<<"PRIVATE_SHOP_NO_FEE_CONTROL_CHECKS="<<checks<<" FAILURES="<<failures<<'\n';return failures?1:0;}
